sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = {};
    try {
        body = typeof request.body.data === 'string' ? JSON.parse(request.body.data) : (request.body.data || {});
        if (!body.prompt && request.body.dataString) {
            body = JSON.parse(request.body.dataString);
        }
    } catch (e) {
        response.setStatus(400);
        response.setBody({ result: { success: false, error: 'Invalid JSON request body' } });
        return;
    }

    var promptText = body.prompt || body.command || body.text;
    if (!promptText) {
        response.setStatus(400);
        response.setBody({ result: { success: false, error: 'Missing required field "prompt" in request body.' } });
        return;
    }

    var parser = new x_2056099_indust_0.PromptIntelligentParser();
    var result = parser.processPrompt(promptText, gs.getUserID());

    if (!result.success) {
        var isAuthError = result.error && result.error.indexOf('Access denied') > -1;
        response.setStatus(isAuthError ? 403 : 400);
    }
    response.setBody({ result: result });
})(request, response);
